//! The licenses json-diff ships under, shown by Help > Licenses.

/// The licenses of every bundled third-party library; regenerated by
/// scripts/notices.sh.
const THIRD_PARTY_NOTICES: &str = include_str!("../../../THIRD_PARTY_NOTICES.txt");

#[tauri::command]
pub fn licenses() -> &'static str {
    THIRD_PARTY_NOTICES
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn notices_cover_both_rust_and_javascript_libraries() {
        assert!(THIRD_PARTY_NOTICES.contains("Rust libraries"));
        assert!(THIRD_PARTY_NOTICES.contains("\nJavaScript libraries\n"));
        assert!(THIRD_PARTY_NOTICES.contains("monaco-editor"));
    }
}
